import java.util.*;
import java.io.*;

public class CF552C {
    private static int maxPower;
    private static int base;
    private static Set<Long> possibleSums;

    public static void main(String[] args) throws Exception {
        InputReader in = new InputReader(System.in);
        PrintWriter writer = new PrintWriter(new OutputStreamWriter(System.out));

        base = in.nextInt();
        long n = in.nextLong();

        maxPower = 0;
        for (int i = 0; base > 2 && i < 21; i++) {
            maxPower = i;
            if (Math.pow(base, i) > 1e9) break;
        }

        possibleSums = new HashSet<>();
        if (base > 2) {
            computeAllSums(0, 0L);
        }

        boolean answer = (base == 2);
        if (!answer) {
            for (long val : possibleSums) {
                if (val >= n && possibleSums.contains(val - n)) {
                    answer = true;
                    break;
                }
            }
        }

        writer.println(answer ? "YES" : "NO");
        writer.close();
    }

    private static void computeAllSums(int powerIndex, long currentSum) {
        if (powerIndex > maxPower) {
            possibleSums.add(currentSum);
            return;
        }
        computeAllSums(powerIndex + 1, currentSum + (long) Math.pow(base, powerIndex));
        computeAllSums(powerIndex + 1, currentSum);
    }

    static class InputReader {
        private BufferedReader bufferedReader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream inputStream) {
            bufferedReader = new BufferedReader(new InputStreamReader(inputStream));
            tokenizer = null;
        }

        public String next() throws Exception {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(bufferedReader.readLine());
            }
            return tokenizer.nextToken();
        }

        public String nextLine() throws Exception {
            tokenizer = null;
            return bufferedReader.readLine();
        }

        public int nextInt() throws Exception {
            return Integer.parseInt(next());
        }

        public double nextDouble() throws Exception {
            return Double.parseDouble(next());
        }

        public long nextLong() throws Exception {
            return Long.parseLong(next());
        }
    }
}
